fn findMax(a: &[i32], n: usize) -> usize {
    // Preconditions based on the problem statement:
    // - a.len() > 0
    // - 0 < n <= a.len()
    debug_assert!(!a.is_empty(), "The array must be non-empty");
    debug_assert!(n <= a.len(), "Prefix length must not exceed array length");
    debug_assert!(n > 0, "Prefix length must be strictly positive");

    // Initialize the maximum value and index to the first element in the prefix
    let mut max_index = 0;
    let mut max_value = a[0];

    // Scan the rest of the prefix [1..n) and update on strictly greater values
    for i in 1..n {
        if a[i] > max_value {
            max_value = a[i];
            max_index = i;
        }
    }

    max_index
}

